const raw = $input.first().json.id;

if (!raw) {
  return { json: {} };
}

// Remove the 'yt:video:' prefix to get just the ID
const id = raw.replace('yt:video:', '');

// Return the extracted ID
return {
  json: {
    id: id
  }
};

// Video metadata from the "Get a video" node
const video = $('Get a video').item.json;
const title = video.snippet?.title || 'Untitled video';
const description = video.snippet?.description || 'No description provided.';
const videoId = video.id;

// Original YouTube link (falls back to a constructed URL if missing)
const link = $('YouTube RSS Trigger').item.json.link || `https://www.youtube.com/watch?v=${videoId}`;

// AI summary from the Gemini response (this node's input)
const ai = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || 'No summary available.';

// Build the full message with title, link, description and AI summary
const message = [
  `**${title}**`,
  link,
  '',
  '**Description:**',
  description,
  '',
  '**AI Summary:**',
  ai
].join('\n');

// Discord messages are capped at 2000 characters (not 4000). Split on
// line breaks first so words/markdown don't get cut mid-sentence, then
// hard-split anything still too long.
const DISCORD_LIMIT = 2000;
const lines = message.split('\n');
const chunks = [];
let current = '';

for (const line of lines) {
  const candidate = current ? `${current}\n${line}` : line;
  if (candidate.length > DISCORD_LIMIT) {
    if (current) chunks.push(current);
    if (line.length > DISCORD_LIMIT) {
      for (let i = 0; i < line.length; i += DISCORD_LIMIT) {
        chunks.push(line.slice(i, i + DISCORD_LIMIT));
      }
      current = '';
    } else {
      current = line;
    }
  } else {
    current = candidate;
  }
}
if (current) chunks.push(current);

return chunks.map(chunk => ({ json: { text: chunk , length :chunk.length} }));

